public class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate and normalize inputs
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set is null or empty');
        }

        String normalizedBase = normalizeCurrency(baseCurrency);
        if (normalizedBase == null) {
            throw new ExchangeRateException('Base currency is invalid');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalizedQuote = normalizeCurrency(quote);
            if (normalizedQuote == null) {
                throw new ExchangeRateException('Quote currency ' + quote + ' is invalid');
            }
            normalizedQuotes.add(normalizedQuote);
        }

        // Build request URL with query parameters
        String symbols = String.join(new List<String>(normalizedQuotes), ',');
        String url = 'callout:FB_Exchange_Rates/v1/latest?base=' + normalizedBase + '&symbols=' + symbols;

        // Create HTTP request
        HttpRequest req = new HttpRequest();
        req.setMethod('GET');
        req.setEndpoint(url);
        req.setHeader('Accept', 'application/json');

        // Perform callout with retry for 503
        HttpResponse res = makeCallout(req);
        if (res.getStatusCode() == 503) {
            res = makeCallout(req); // Retry once
        }

        // Check final status
        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException('API returned status code ' + res.getStatusCode());
        }

        // Parse JSON response
        Map<String, Object> jsonResponse = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        if (jsonResponse == null || !jsonResponse.containsKey('rates')) {
            throw new ExchangeRateException('Response body cannot be parsed or missing rates');
        }

        Map<String, Object> rates = (Map<String, Object>) jsonResponse.get('rates');
        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String quote : normalizedQuotes) {
            if (!rates.containsKey(quote)) {
                throw new ExchangeRateException('Requested currency ' + quote + ' not found in rates');
            }
            Object rateObj = rates.get(quote);
            if (rateObj == null) {
                throw new ExchangeRateException('Rate for currency ' + quote + ' is null');
            }
            result.put(quote, (Decimal) rateObj);
        }

        return result;
    }

    private static HttpResponse makeCallout(HttpRequest req) {
        Http http = new Http();
        return http.send(req);
    }

    private static String normalizeCurrency(String currCode) {
        if (currCode == null) return null;
        String trimmed = currCode.trim().toUpperCase();
        if (trimmed.length() != 3) return null;
        for (Integer i = 0; i < 3; i++) {
            String c = trimmed.substring(i, i + 1);
            if (c < 'A' || c > 'Z') return null;
        }
        return trimmed;
    }
}
