public class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        // Return empty map for null or empty input
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<String, List<Contact>>();
        }

        // Query contacts for the given accountIds, respecting sharing
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            WITH USER_MODE
        ];

        Map<String, List<Contact>> groupedByDomain = new Map<String, List<Contact>>();

        for (Contact c : contacts) {
            // Skip contacts without an email
            if (c.Email == null) {
                continue;
            }

            // Extract domain part (after '@') and lower-case it
            String email = c.Email;
            Integer atIndex = email.indexOf('@');
            if (atIndex != -1) {
                String domain = email.substring(atIndex + 1).toLowerCase();
                if (!groupedByDomain.containsKey(domain)) {
                    groupedByDomain.put(domain, new List<Contact>());
                }
                groupedByDomain.get(domain).add(c);
            }
        }

        return groupedByDomain;
    }
}
