    @isTest
    private static void testVerifyWithNonBlankBillingStreetAnd200ResponseCorrected() {
        // Setup mock for 200 response with status "CORRECTED"
        HttpResponse mockResp = new HttpResponse();
        mockResp.setStatusCode(200);
        mockResp.setBody('{"status": "CORRECTED", "address": {"street": "789 New St", "city": "New City", "postalCode": "12345", "country": "Canada"}}');

        AddressVerificationMock mock = new AddressVerificationMock(mockResp);
        Test.setMock(HttpCalloutMock.class, mock);

