        try {
            AddressVerificationService.verify(acct);
            System.assert(false, 'Expected AddressVerificationException to be thrown');
        } catch (AddressVerificationService.AddressVerificationException e) {
            System.assertEquals('Address API returned HTTP 404', e.getMessage());
        }
