public class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Preprocess: set LeadSource to 'Web' if blank
        for (Lead lead : leads) {
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }

        // Track first occurrence of each email (trimmed, lower-cased)
        Map<String, Integer> emailToFirstIndex = new Map<String, Integer>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndicesForInsert = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            String email = lead.Email;

            if (email != null) {
                String normalizedEmail = email.trim().toLowerCase();
                if (emailToFirstIndex.containsKey(normalizedEmail)) {
                    // Duplicate email
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                } else {
                    // First occurrence of this email
                    emailToFirstIndex.put(normalizedEmail, i);
                    // Add to leadsToInsert
                    leadsToInsert.add(lead);
                    originalIndicesForInsert.add(i);
                }
            } else {
                // No email, never a duplicate
                leadsToInsert.add(lead);
                originalIndicesForInsert.add(i);
            }
        }

        // Perform single DML insert with allOrNone=false
        if (leadsToInsert.size() > 0) {
            List<Database.SaveResult> insertResults = Database.insert(leadsToInsert, false);

            for (Integer j = 0; j < insertResults.size(); j++) {
                Database.SaveResult insertResult = insertResults[j];
                Integer originalIndex = originalIndicesForInsert[j];

                if (insertResult.isSuccess()) {
                    result.insertedIds.add(insertResult.getId());
                    result.successCount++;
                } else {
                    // Join all error messages with '; '
                    List<Database.Error> errors = insertResult.getErrors();
                    String errorMessage = '';
                    for (Database.Error err : errors) {
                        if (errorMessage != '') {
                            errorMessage += '; ';
                        }
                        errorMessage += err.getMessage();
                    }
                    result.errorsByIndex.put(originalIndex, errorMessage);
                }
            }
        }

        return result;
    }
}
