public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // Validate inputs
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object API name and field API name cannot be null or blank.');
        }

        // Get object describe (case-insensitive)
        DescribeSObjectResult objDescribe = getObjectDescribe(objectApiName);
        if (objDescribe == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Get field describe (case-insensitive)
        DescribeFieldResult fieldDescribe = getFieldDescribe(objDescribe, fieldApiName);
        if (fieldDescribe == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        // Check field type
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        // Get picklist values and build options
        List<DescribePicklistEntry> picklistEntries = fieldDescribe.getPicklistValues();
        List<Option> options = new List<Option>();

        for (DescribePicklistEntry entry : picklistEntries) {
            if (entry.getActive()) {
                options.add(new Option(entry.getValue(), entry.getLabel(), entry.getDefault()));
            }
        }

        return options;
    }

    private static DescribeSObjectResult getObjectDescribe(String objectApiName) {
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String lowerCaseObjectName = objectApiName.toLowerCase();

        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase().equals(lowerCaseObjectName)) {
                return globalDescribe.get(key).getDescribe();
            }
        }
        return null;
    }

    private static DescribeFieldResult getFieldDescribe(DescribeSObjectResult objDescribe, String fieldApiName) {
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        String lowerCaseFieldName = fieldApiName.toLowerCase();

        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase().equals(lowerCaseFieldName)) {
                return fieldMap.get(key).getDescribe();
            }
        }
        return null;
    }
}
