public class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        // Build a map of order number to the last event's tracking number and carrier
        Map<String, EventInfo> orderEventMap = new Map<String, EventInfo>();

        for (FB_Shipment_Event__e event : events) {
            if (String.isBlank(event.Order_Number__c)) {
                continue;
            }
            orderEventMap.put(event.Order_Number__c, new EventInfo(event.Tracking_Number__c, event.Carrier__c));
        }

        if (orderEventMap.isEmpty()) {
            return;
        }

        // Query all sales orders for the order numbers in the map
        List<FB_Sales_Order__c> orders = [
            SELECT Order_Number__c, Status__c, Tracking_Number__c, Carrier__c, Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderEventMap.keySet()
        ];

        // Prepare updates for orders that are not cancelled
        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();

        for (FB_Sales_Order__c order : orders) {
            if (order.Status__c == 'Cancelled') {
                continue;
            }
            EventInfo eventInfo = orderEventMap.get(order.Order_Number__c);
            if (eventInfo != null) {
                order.Status__c = 'Shipped';
                order.Tracking_Number__c = eventInfo.trackingNumber;
                order.Carrier__c = eventInfo.carrier;
                order.Shipped_Date__c = Date.today();
                ordersToUpdate.add(order);
            }
        }

        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }

    private class EventInfo {
        String trackingNumber;
        String carrier;

        EventInfo(String trackingNumber, String carrier) {
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }
}
