public class OpportunityPipelineHandler {

    public static void handleTriggerEvents(List<Opportunity> newOps, List<Opportunity> oldOps) {
        Set<Id> accountsToUpdate = new Set<Id>();

        // Handle insert
        if (Trigger.isInsert) {
            for (Opportunity opp : newOps) {
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountsToUpdate.add(opp.AccountId);
                }
            }
        }

        // Handle update
        if (Trigger.isUpdate) {
            Map<Id, Opportunity> newMap = new Map<Id, Opportunity>(newOps);
            Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(oldOps);

            for (Opportunity newOpp : newOps) {
                Opportunity oldOpp = oldMap.get(newOpp.Id);

                // AccountId changed
                if (newOpp.AccountId != oldOpp.AccountId) {
                    if (oldOpp.AccountId != null && !oldOpp.IsClosed) {
                        accountsToUpdate.add(oldOpp.AccountId);
                    }
                    if (newOpp.AccountId != null && !newOpp.IsClosed) {
                        accountsToUpdate.add(newOpp.AccountId);
                    }
                } else {
                    // IsClosed changed (stage change between open/closed)
                    if (newOpp.IsClosed != oldOpp.IsClosed) {
                        accountsToUpdate.add(newOpp.AccountId);
                    }
                    // Amount changed and opportunity is open
                    if (newOpp.Amount != oldOpp.Amount && !newOpp.IsClosed) {
                        accountsToUpdate.add(newOpp.AccountId);
                    }
                }
            }
        }

        // Handle delete
        if (Trigger.isDelete) {
            for (Opportunity opp : oldOps) {
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountsToUpdate.add(opp.AccountId);
                }
            }
        }

        // Handle undelete
        if (Trigger.isUndelete) {
            for (Opportunity opp : newOps) {
                if (opp.AccountId != null && !opp.IsClosed) {
                    accountsToUpdate.add(opp.AccountId);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            updateAccountTotals(accountsToUpdate);
        }
    }

    private static void updateAccountTotals(Set<Id> accountIds) {
        // Query all open opportunities for these accounts
        List<Opportunity> openOps = [
            SELECT AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
        ];

        // Aggregate by account
        Map<Id, Decimal> pipelineSum = new Map<Id, Decimal>();
        Map<Id, Integer> opportunityCount = new Map<Id, Integer>();

        for (Opportunity opp : openOps) {
            Id accId = opp.AccountId;
            Decimal amount = opp.Amount != null ? opp.Amount : 0;

            pipelineSum.put(accId, (pipelineSum.get(accId) == null ? 0 : pipelineSum.get(accId)) + amount);
            opportunityCount.put(accId, (opportunityCount.get(accId) == null ? 0 : opportunityCount.get(accId)) + 1);
        }

        // Prepare accounts to update
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account acc = new Account(Id = accId);
            // Use 0 if the account is not in the maps (no open opportunities)
            acc.FB_Open_Pipeline__c = pipelineSum.containsKey(accId) ? pipelineSum.get(accId) : 0;
            acc.FB_Open_Opportunities__c = opportunityCount.containsKey(accId) ? opportunityCount.get(accId) : 0;
            accountsToUpdate.add(acc);
        }

        update accountsToUpdate;
    }
}
