public class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Integer currentYear = Date.today().year();
        Date startDate = Date.newInstance(currentYear, 1, 1);
        Date endDate = Date.newInstance(currentYear, 12, 31);

        List<AggregateResult> aggResults = [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
                AND IsWon = true
                AND CloseDate >= :startDate
                AND CloseDate <= :endDate
            GROUP BY AccountId
        ];

        Map<Id, Decimal> sumMap = new Map<Id, Decimal>();
        for (AggregateResult agg : aggResults) {
            Id accountId = (Id) agg.get('AccountId');
            Decimal total = (Decimal) agg.get('totalAmount');
            if (total == null) {
                total = 0;
            }
            sumMap.put(accountId, total);
        }

        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            if (sumMap.containsKey(accountId)) {
                result.put(accountId, sumMap.get(accountId));
            } else {
                result.put(accountId, 0);
            }
        }

        return result;
    }
}
