public class DealEventPublisher {
    /**
     * Publishes a Deal_Stage_Change__e platform event for each Opportunity in the input list.
     * Each event contains the Opportunity's Id, StageName, and Amount.
     * 
     * @param opportunities List of Opportunity records to process
     * @return List of Database.SaveResult objects in the same order as the input opportunities
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> publishResults = new List<Database.SaveResult>();

        // If the input list is null or empty, return an empty list
        if (opportunities == null || opportunities.isEmpty()) {
            return publishResults;
        }

        // Iterate through each opportunity and publish a platform event for it
        for (Opportunity opp : opportunities) {
            // Create a new platform event instance
            Deal_Stage_Change__e event = new Deal_Stage_Change__e();

            // Set the event fields from the opportunity record
            event.Opportunity_Id__c = opp.Id;
            event.Stage__c = opp.StageName;
            event.Amount__c = opp.Amount;

            // Publish the event - EventBus.publish returns a List<Database.SaveResult>
            List<Database.SaveResult> eventResults = EventBus.publish(event);

            // Add the SaveResult to our results list (eventResults should contain one element)
            if (!eventResults.isEmpty()) {
                publishResults.add(eventResults[0]);
            }
        }

        return publishResults;
    }
}
