public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        // Build a map of normalized email to Contact Id for efficient lookup
        Map<String, Id> emailToContactId = new Map<String, Id>();

        for (Contact contact : contacts) {
            String contactEmail = contact.Email;
            if (String.isBlank(contactEmail)) {
                continue; // Blank email never matches
            }
            String normalizedEmail = contactEmail.trim().toLowerCase();
            // Only add if not already in map (to keep first contact in order)
            if (!emailToContactId.containsKey(normalizedEmail)) {
                emailToContactId.put(normalizedEmail, contact.Id);
            }
        }

        List<Id> result = new List<Id>();

        for (Lead lead : leads) {
            String leadEmail = lead.Email;
            if (String.isBlank(leadEmail)) {
                result.add(null); // Blank email never matches
            } else {
                String normalizedEmail = leadEmail.trim().toLowerCase();
                Id matchedId = emailToContactId.get(normalizedEmail);
                result.add(matchedId); // Will be null if not found
            }
        }

        return result;
    }
}
