        Case oldCase = oldCaseMap.get(newCase.Id);

        // Check if IsClosed changed from false to true
        if (oldCase != null && !oldCase.IsClosed && newCase.IsClosed) {
            // Check if the case has a contact
            if (newCase.ContactId != null) {
                caseIdsToProcess.add(newCase.Id);
            }
        }
    }

    // Batch case IDs to avoid exceeding queueable job limit (50 per transaction)
    // Enqueue one job per 50 cases
    Integer batchSize = 50;
    for (Integer i = 0; i < caseIdsToProcess.size(); i += batchSize) {
        Integer end = Math.min(i + batchSize, caseIdsToProcess.size());
        List<Id> batchCaseIds = caseIdsToProcess.sublist(i, end);
        System.enqueueJob(new CaseSurveyJob(batchCaseIds));
    }
}
