import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track searchTerm = '';
    @track contacts = [];
    @track error = null;

    debounceTimer;
    currentRequestId = 0;

    handleSearchChange(event) {
        this.searchTerm = event.target.value;

        // Clear any existing debounce timer
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
        }

        // Trim the search term
        const trimmedTerm = this.searchTerm.trim();

        // If trimmed term has fewer than 2 characters, clear results and return
        if (trimmedTerm.length < 2) {
            this.contacts = [];
            this.error = null;
            return;
        }

        // Set up debounce timer for 300ms
        this.debounceTimer = setTimeout(() => {
            // Increment request ID to track the most recent request
            this.currentRequestId++;
            const requestId = this.currentRequestId;

            // Call Apex method imperatively
            searchContacts({ searchTerm: trimmedTerm })
                .then((result) => {
                    // Only update results if this is the most recent request
                    if (requestId === this.currentRequestId) {
                        this.contacts = result;
                        this.error = null;
                    }
                })
                .catch((error) => {
                    // Only update error if this is the most recent request
                    if (requestId === this.currentRequestId) {
                        this.error = error;
                        this.contacts = [];
                    }
                });
        }, 300);
    }

    // Clean up when component is removed
    disconnectedCallback() {
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
        }
    }
}
