import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;
        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        // Get the internal input elements from lightning-input refs
        const fullNameInput = this.refs.fullName.inputElement;
        const emailInput = this.refs.email.inputElement;
        const companyInput = this.refs.company.inputElement;

        // Step 1: Validate email domain
        const emailDomain = this.email.split('@')[1]?.toLowerCase();
        const forbiddenDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

        if (forbiddenDomains.includes(emailDomain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: Report validity on all inputs
        fullNameInput.reportValidity();
        emailInput.reportValidity();
        companyInput.reportValidity();

        // Step 3: Check if any input is invalid
        if (!fullNameInput.validity.valid || !emailInput.validity.valid || !companyInput.validity.valid) {
            return;
        }

        // Step 4: Call Apex method imperatively
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(result => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch(error => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
