public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: Get all existing Affiliations for these contacts
        List<npe5__Affiliation__c> existingAffiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
        ];

        // Query 2: Get the Contact records with their primary affiliation lookup
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ];

        // Build maps for efficient lookup
        Map<Id, List<npe5__Affiliation__c>> affiliationsByContact = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c aff : existingAffiliations) {
            if (!affiliationsByContact.containsKey(aff.npe5__Contact__c)) {
                affiliationsByContact.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            affiliationsByContact.get(aff.npe5__Contact__c).add(aff);
        }

        Map<Id, Contact> contactMap = new Map<Id, Contact>();
        for (Contact c : contacts) {
            contactMap.put(c.Id, c);
        }

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        Date today = Date.today();

        // Process each contact
        for (Id contactId : contactIds) {
            Id newOrgId = employerByContactId.get(contactId);
            Contact contact = contactMap.get(contactId);

            // Get existing affiliations for this contact
            List<npe5__Affiliation__c> contactAffiliations = affiliationsByContact.get(contactId);

            // Find the current primary affiliation's organization (if any)
            Id currentPrimaryOrgId = null;
            if (contactAffiliations != null) {
                for (npe5__Affiliation__c aff : contactAffiliations) {
                    if (aff.npe5__Primary__c && aff.npe5__Status__c == 'Current') {
                        currentPrimaryOrgId = aff.npe5__Organization__c;
                        break;
                    }
                }
            }

            // If the new organization is already the primary affiliation, skip
            if (currentPrimaryOrgId == newOrgId) {
                continue;
            }

            // Create new primary affiliation with the new organization
            npe5__Affiliation__c newAffiliation = new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = newOrgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = today
            );
            affiliationsToInsert.add(newAffiliation);

            // Update Contact's primary affiliation lookup to the new Organization
            contact.npsp__Primary_Affiliation__c = newOrgId;
            contactsToUpdate.add(contact);
        }

        // DML 1: Insert new affiliations
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }

        // DML 2: Update contacts with new primary affiliation
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
