public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        // Return empty list for null or empty input
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage one NPSP Data Import record per gift
        List<npsp__DataImport__c> dataImportRecords = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            npsp__DataImport__c dataImport = new npsp__DataImport__c();
            dataImport.npsp__Contact1_Firstname__c = gift.firstName;
            dataImport.npsp__Contact1_Lastname__c = gift.lastName;
            dataImport.npsp__Contact1_Personal_Email__c = gift.email;
            dataImport.npsp__Donation_Amount__c = gift.amount;
            dataImport.npsp__Donation_Date__c = gift.giftDate;
            dataImportRecords.add(dataImport);
        }

        // Insert the data import records
        insert dataImportRecords;

        // Process the data imports synchronously using NPSP's Apex API
        npsp__DataImporter.process(dataImportRecords);

        // Query the updated data import records to get import results
        List<npsp__DataImport__c> processedRecords = [
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c, npsp__DonationImported__c, 
                   npsp__FailureInformation__c, npsp__Contact1_Personal_Email__c,
                   npsp__Donation_Amount__c, npsp__Donation_Date__c
            FROM npsp__DataImport__c
            WHERE Id IN :dataImportRecords
        ];

        // Map processed records by Id for easy lookup
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>();
        for (npsp__DataImport__c rec : processedRecords) {
            processedMap.put(rec.Id, rec);
        }

        // Bulk query Contacts by email to get ContactIds
        Set<String> emails = new Set<String>();
        for (npsp__DataImport__c rec : processedRecords) {
            if (rec.npsp__Contact1_Personal_Email__c != null) {
                emails.add(rec.npsp__Contact1_Personal_Email__c);
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (!emails.isEmpty()) {
            List<Contact> contacts = [SELECT Id, Email FROM Contact WHERE Email IN :emails];
            for (Contact c : contacts) {
                emailToContactId.put(c.Email, c.Id);
            }
        }

        // Bulk query Opportunities by amount and date to get OpportunityIds
        Set<Decimal> amounts = new Set<Decimal>();
        Set<Date> dates = new Set<Date>();
        for (npsp__DataImport__c rec : processedRecords) {
            if (rec.npsp__Donation_Amount__c != null) {
                amounts.add(rec.npsp__Donation_Amount__c);
            }
            if (rec.npsp__Donation_Date__c != null) {
                dates.add(rec.npsp__Donation_Date__c);
            }
        }

        Map<Decimal, Map<Date, Id>> amountDateToOpportunityId = new Map<Decimal, Map<Date, Id>>();
        if (!amounts.isEmpty() && !dates.isEmpty()) {
            List<Opportunity> opportunities = [SELECT Id, Amount, CloseDate FROM Opportunity WHERE Amount IN :amounts AND CloseDate IN :dates];
            for (Opportunity o : opportunities) {
                if (!amountDateToOpportunityId.containsKey(o.Amount)) {
                    amountDateToOpportunityId.put(o.Amount, new Map<Date, Id>());
                }
                amountDateToOpportunityId.get(o.Amount).put(o.CloseDate, o.Id);
            }
        }

        // Build ImportResult list in input order
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c originalDataImport : dataImportRecords) {
            npsp__DataImport__c processedDataImport = processedMap.get(originalDataImport.Id);
            ImportResult result = new ImportResult();

            // Check if NPSP imported the row successfully
            if (processedDataImport.npsp__Status__c == 'Imported' && 
                processedDataImport.npsp__Contact1Imported__c == true && 
                processedDataImport.npsp__DonationImported__c == true) {
                result.success = true;

                // Get ContactId from the email map
                if (processedDataImport.npsp__Contact1_Personal_Email__c != null && 
                    emailToContactId.containsKey(processedDataImport.npsp__Contact1_Personal_Email__c)) {
                    result.contactId = emailToContactId.get(processedDataImport.npsp__Contact1_Personal_Email__c);
                }

                // Get OpportunityId from the amount/date map
                if (processedDataImport.npsp__Donation_Amount__c != null && 
                    processedDataImport.npsp__Donation_Date__c != null) {
                    Map<Date, Id> dateToOpportunityId = amountDateToOpportunityId.get(processedDataImport.npsp__Donation_Amount__c);
                    if (dateToOpportunityId != null && 
                        dateToOpportunityId.containsKey(processedDataImport.npsp__Donation_Date__c)) {
                        result.opportunityId = dateToOpportunityId.get(processedDataImport.npsp__Donation_Date__c);
                    }
                }

                result.errorMessage = null;
            } else {
                result.success = false;
                result.contactId = null;
                result.opportunityId = null;
                result.errorMessage = processedDataImport.npsp__FailureInformation__c;
            }

            results.add(result);
        }

        return results;
    }
}
