                c.Name = 'Unknown';
            }
        }

        // Insert the contacts
        insert members;

        // Get the Household Account Record Type Id
        RecordType householdRecordType = [
            SELECT Id 
            FROM RecordType 
            WHERE SobjectType = 'Account' 
            AND DeveloperName = 'HH_Account'
            LIMIT 1
        ];

        // Create the Household Account
        Account householdAccount = new Account(
            RecordTypeId = householdRecordType.Id,
            npe01__One2OneContact__c = members[0].Id
        );
        insert householdAccount;

        return householdAccount.Id;
    }
