public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newList, List<SObject> oldList, npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {

        // Only process AfterInsert and AfterUpdate on Opportunity
        if (triggerAction != npsp.TDTM_Runnable.Action.AFTER_INSERT && triggerAction != npsp.TDTM_Runnable.Action.AFTER_UPDATE) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        List<Opportunity> oppsToProcess = new List<Opportunity>();

        // For AfterInsert: check if new opportunities are Closed Won with Amount >= 5000
        if (triggerAction == npsp.TDTM_Runnable.Action.AFTER_INSERT) {
            for (Opportunity opp : (List<Opportunity>)newList) {
                if (opp.StageName == 'Closed Won' && opp.Amount >= 5000) {
                    oppsToProcess.add(opp);
                }
            }
        }

        // For AfterUpdate: check if opportunities became Closed Won with Amount >= 5000
        if (triggerAction == npsp.TDTM_Runnable.Action.AFTER_UPDATE) {
            Map<Id, Opportunity> oldOppMap = new Map<Id, Opportunity>();
            for (Opportunity oldOpp : (List<Opportunity>)oldList) {
                oldOppMap.put(oldOpp.Id, oldOpp);
            }

            for (Opportunity newOpp : (List<Opportunity>)newList) {
                Opportunity oldOpp = oldOppMap.get(newOpp.Id);
                // Check if newOpp is Closed Won with Amount >= 5000
                // and oldOpp was not Closed Won or Amount < 5000
                if (newOpp.StageName == 'Closed Won' && newOpp.Amount >= 5000) {
                    if (oldOpp == null || oldOpp.StageName != 'Closed Won' || oldOpp.Amount < 5000) {
                        oppsToProcess.add(newOpp);
                    }
                }
            }
        }

        // If no opportunities qualify, return empty wrapper
        if (oppsToProcess.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        // Get IDs of qualifying opportunities
        Set<Id> oppIds = new Set<Id>();
        for (Opportunity opp : oppsToProcess) {
            oppIds.add(opp.Id);
        }

        // Query existing tasks with subject 'Major gift thank-you call' for these opportunities
        List<Task> existingTasks = [SELECT WhatId FROM Task WHERE WhatId IN :oppIds AND Subject = 'Major gift thank-you call'];

        // Create a set of opportunity IDs that already have a task
        Set<Id> oppIdsWithTasks = new Set<Id>();
        for (Task t : existingTasks) {
            oppIdsWithTasks.add(t.WhatId);
        }

        // Prepare tasks to insert
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : oppsToProcess) {
            // Skip if task already exists for this opportunity
            if (oppIdsWithTasks.contains(opp.Id)) {
                continue;
            }

            Task newTask = new Task();
            newTask.Subject = 'Major gift thank-you call';
            newTask.Priority = 'High';
            newTask.Status = 'Not Started';
            newTask.WhatId = opp.Id;
            newTask.WhoId = opp.npsp__Primary_Contact__c; // May be null
            newTask.OwnerId = opp.OwnerId;
            newTask.ActivityDate = opp.CloseDate.addDays(3);

            tasksToInsert.add(newTask);
        }

        // Insert tasks if any
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return new npsp.TDTM_Runnable.DmlWrapper(tasksToInsert);
    }
}
