public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        // Return empty set if input is null or empty
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        // Get the current user's ID
        Id currentUserId = UserInfo.getUserId();

        // UserRecordAccess can only query up to 200 records at a time
        Integer batchSize = 200;
        Set<Id> editableSet = new Set<Id>();

        // Process records in batches
        List<Id> recordList = new List<Id>(recordIds);
        for (Integer i = 0; i < recordList.size(); i += batchSize) {
            Integer endIndex = Math.min(i + batchSize, recordList.size());
            List<Id> batchIds = new List<Id>();
            for (Integer j = i; j < endIndex; j++) {
                batchIds.add(recordList[j]);
            }

            // Query UserRecordAccess for this batch with UserId filter
            List<UserRecordAccess> userRecordAccesses = [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :batchIds
            ];

            // Add IDs with edit access to the result set
            for (UserRecordAccess ura : userRecordAccesses) {
                if (ura.HasEditAccess) {
                    editableSet.add(ura.RecordId);
                }
            }
        }

        return editableSet;
    }
}
