    public static List<FB_Employee__c> getDirectory() {
        // Check if the user can read the FB_Employee__c object
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Get describe results for each field to check accessibility
        Schema.DescribeFieldResult departmentFieldDescribe = FB_Employee__c.Department__c.getDescribe();
        Schema.DescribeFieldResult salaryFieldDescribe = FB_Employee__c.Salary__c.getDescribe();
        Schema.DescribeFieldResult personalEmailFieldDescribe = FB_Employee__c.Personal_Email__c.getDescribe();

        Boolean canReadDepartment = departmentFieldDescribe.isAccessible();
        Boolean canReadSalary = salaryFieldDescribe.isAccessible();
        Boolean canReadPersonalEmail = personalEmailFieldDescribe.isAccessible();

        // Build the SOQL query dynamically based on accessible fields
        String query = 'SELECT Id, Name';
        if (canReadDepartment) {
            query += ', Department__c';
        }
        if (canReadSalary) {
            query += ', Salary__c';
        }
        if (canReadPersonalEmail) {
            query += ', Personal_Email__c';
        }
        query += ' FROM FB_Employee__c ORDER BY Name ASC';

        // Execute the query and return the results
        return Database.query(query);
    }
}
