        for (SObject sobj : triggerNew) {
            if (sobj instanceof Opportunity) {
                Opportunity newOpp = (Opportunity)sobj;
                Opportunity oldOpp = (Opportunity)oldMap.get(sobj.Id);
                if (newOpp.StageName != oldOpp.StageName) {
                    opportunityIdsToSync.add(sobj.Id);
                }
            }
        }
    }

    public static Set<Id> getOpportunityIdsToSync() {
        return opportunityIdsToSync;
