public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        handleContacts((List<Contact>)triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>)triggerNew;
        List<Contact> oldContacts = (List<Contact>)triggerOld;
        handleContacts(newContacts, oldContacts);
    }

    private void handleContacts(List<Contact> newContacts, List<Contact> oldContacts) {
        List<Contact> contactsToCheck = new List<Contact>();

        if (oldContacts == null) {
            // Insert context: check all contacts with AccountId and Email
            for (Contact c : newContacts) {
                if (c.AccountId != null && c.Email != null) {
                    contactsToCheck.add(c);
                }
            }
        } else {
            // Update context: only check if Email or AccountId changed
            Map<Id, Contact> oldMap = new Map<Id, Contact>(oldContacts);
            for (Contact c : newContacts) {
                Contact oldC = oldMap.get(c.Id);
                if ((c.Email != oldC.Email || c.AccountId != oldC.AccountId) 
                    && c.AccountId != null && c.Email != null) {
                    contactsToCheck.add(c);
                }
            }
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        // Collect unique AccountIds and lowercase Emails for querying
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : contactsToCheck) {
            accountIds.add(c.AccountId);
            emails.add(c.Email.toLowerCase());
        }

        // Single SOQL query to fetch existing contacts with matching AccountId/Email
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email IN :emails
        ];

        // Build map of AccountId -> set of lowercase emails already in use
        Map<Id, Set<String>> accountEmails = new Map<Id, Set<String>>();
        for (Contact c : existingContacts) {
            if (!accountEmails.containsKey(c.AccountId)) {
                accountEmails.put(c.AccountId, new Set<String>());
            }
            accountEmails.get(c.AccountId).add(c.Email.toLowerCase());
        }

        // Track emails accepted in this batch (first in list wins)
        Map<Id, Set<String>> acceptedEmails = new Map<Id, Set<String>>();

        for (Contact c : contactsToCheck) {
            String lowerEmail = c.Email.toLowerCase();
            Id accountId = c.AccountId;

            // Check against existing contacts in database
            if (accountEmails.containsKey(accountId) && accountEmails.get(accountId).contains(lowerEmail)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

            // Check against contacts already accepted in this batch
            if (acceptedEmails.containsKey(accountId) && acceptedEmails.get(accountId).contains(lowerEmail)) {
                c.addError('Another contact on this account already uses this email address.');
                continue;
            }

            // Accept this contact - add its email to the accepted set
            if (!acceptedEmails.containsKey(accountId)) {
                acceptedEmails.put(accountId, new Set<String>());
            }
            acceptedEmails.get(accountId).add(lowerEmail);
        }
    }
}
