public with sharing class TA_Case_RollupOpenCount implements 
    TriggerAction.AfterInsert, 
    TriggerAction.AfterUpdate, 
    TriggerAction.AfterDelete, 
    TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        processCases(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        processCases(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        processCases(null, triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        processCases(triggerNew, null);
    }

    private void processCases(List<Case> newCases, List<Case> oldCases) {
        // Collect all affected Account IDs
        Set<Id> accountIds = new Set<Id>();

        // For after insert/undelete: newCases have the current state
        if (newCases != null) {
            for (Case c : newCases) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        // For after update: compare old and new states
        if (newCases != null && oldCases != null) {
            Map<Id, Case> oldCaseMap = new Map<Id, Case>();
            for (Case c : oldCases) {
                oldCaseMap.put(c.Id, c);
            }

            for (Case newCase : newCases) {
                Case oldCase = oldCaseMap.get(newCase.Id);

                // If the case was open and had an account in old state, but now is closed or account changed
                if (oldCase.AccountId != null && !oldCase.IsClosed) {
                    if (newCase.IsClosed || newCase.AccountId != oldCase.AccountId) {
                        accountIds.add(oldCase.AccountId);
                    }
                }

                // If the case is now open and has an account, but wasn't open/had account before
                if (newCase.AccountId != null && !newCase.IsClosed) {
                    if (oldCase == null || oldCase.IsClosed || oldCase.AccountId != newCase.AccountId) {
                        accountIds.add(newCase.AccountId);
                    }
                }
            }
        }

        // For after delete: oldCases have the state before deletion
        if (oldCases != null) {
            for (Case c : oldCases) {
                if (c.AccountId != null && !c.IsClosed) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        // If no accounts to update, return
        if (accountIds.isEmpty()) {
            return;
        }

        // Query all open cases for these accounts
        List<Case> openCases = [
            SELECT AccountId 
            FROM Case 
            WHERE AccountId IN :accountIds 
            AND IsClosed = false
        ];

        // Build count map
        Map<Id, Integer> accountCountMap = new Map<Id, Integer>();
        for (Case c : openCases) {
            if (accountCountMap.containsKey(c.AccountId)) {
                accountCountMap.put(c.AccountId, accountCountMap.get(c.AccountId) + 1);
            } else {
                accountCountMap.put(c.AccountId, 1);
            }
        }

        // Update accounts with the counts
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Account acc = new Account(Id = accId);
            acc.FB_Open_Case_Count__c = accountCountMap.containsKey(accId) ? accountCountMap.get(accId) : 0;
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
