public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    // Static set to track Opportunity Ids that have already had a Task created in this transaction.
    // This ensures only one Task per Opportunity per transaction, even when the trigger re-runs
    // due to the rounding action (TA_Opportunity_RoundAmount) updating the same Opportunities.
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Check if Amount actually changed
            if (newOpp.Amount != oldOpp.Amount) {
                // Only create a Task if we haven't already logged this Opportunity in this transaction
                if (!loggedOpportunityIds.contains(newOpp.Id)) {
                    loggedOpportunityIds.add(newOpp.Id);

                    Task t = new Task(
                        Subject = 'Amount changed',
                        WhatId = newOpp.Id,
                        Status = 'Completed'
                    );
                    tasksToCreate.add(t);
                }
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
